#!/usr/bin/env node
/**
 * Bundle the snapshot Lambda (lambdas/src/snapshot.ts) into a deterministic
 * zip and embed it in src/generated/lambda-bundle.ts, so the sidecar deploys
 * WITHOUT any build tooling at runtime (the MailPoppy pattern). The code key
 * is content-addressed: unchanged code re-deploys to the same S3 object.
 */
import * as esbuild from "esbuild";
import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { deterministicZip } from "./lib/zip.mjs";

const here = dirname(fileURLToPath(import.meta.url));
const sidecarRoot = resolve(here, "..");
const repoRoot = resolve(sidecarRoot, "..", "..", "..");
const entry = join(repoRoot, "lambdas", "src", "snapshot.ts");
const genDir = join(sidecarRoot, "src", "generated");

const result = await esbuild.build({
  entryPoints: [entry],
  bundle: true,
  platform: "node",
  target: "node22",
  format: "cjs",
  // The nodejs22.x runtime provides the AWS SDK v3 — keep it out of the zip.
  external: ["@aws-sdk/*"],
  write: false,
  minify: true,
  legalComments: "none",
});
const js = Buffer.from(result.outputFiles[0].contents);

let epoch = Number(process.env.SOURCE_DATE_EPOCH || 0);
if (!epoch) {
  try {
    epoch = Number(execFileSync("git", ["log", "-1", "--format=%ct"], { cwd: repoRoot }).toString().trim()) || 0;
  } catch {
    epoch = 0;
  }
}

const zip = deterministicZip([{ name: "snapshot.js", data: js }], epoch);
const key = `snapshot-${createHash("sha256").update(js).digest("hex").slice(0, 16)}.zip`;

mkdirSync(genDir, { recursive: true });
writeFileSync(
  join(genDir, "lambda-bundle.ts"),
  [
    "// AUTO-GENERATED by scripts/build-lambda-bundle.mjs — do not edit (git-ignored).",
    `export const lambdaCodeKey = ${JSON.stringify(key)};`,
    `export const lambdaZipBase64 = ${JSON.stringify(zip.toString("base64"))};`,
    "",
  ].join("\n"),
);
console.log(`✅ lambda bundle ${key} (${(zip.length / 1024).toFixed(0)} KB)`);
